<style id="elasticsearch-monitoring-theme-css">
html[data-theme="dark"]{color-scheme:dark;background:#0b1220}html[data-theme="dark"] body{background:#0b1220!important;color:#e5eaf3!important}
html[data-theme="dark"] .card,html[data-theme="dark"] .panel,html[data-theme="dark"] .bg-white{background:#151f30!important;border-color:#2b394d!important;color:#e5eaf3!important}
html[data-theme="dark"] .table{--bs-table-bg:transparent;--bs-table-color:#d5deeb;--bs-table-border-color:#2b394d;color:#d5deeb}
html[data-theme="dark"] .table thead th{background:#101a29!important;color:#aab8cc!important}html[data-theme="dark"] .table td{color:#cbd5e1!important;border-color:#2b394d!important}
html[data-theme="dark"] input,html[data-theme="dark"] select,html[data-theme="dark"] textarea,html[data-theme="dark"] .form-control,html[data-theme="dark"] .form-select{background:#101a29!important;color:#e5eaf3!important;border-color:#39485e!important}
html[data-theme="dark"] .text-dark,html[data-theme="dark"] .text-body{color:#e5eaf3!important}html[data-theme="dark"] .text-secondary{color:#9aa9bd!important}
#elasticsearch-monitoring-theme-picker{position:fixed;right:18px;bottom:18px;z-index:99999;display:flex;align-items:center;gap:8px;padding:9px 11px;border:1px solid #d9e0ea;border-radius:12px;background:#fff;color:#263348;box-shadow:0 8px 28px #15223826;font:600 12px/1.2 system-ui,sans-serif}
#elasticsearch-monitoring-theme-picker select{border:0;background:transparent;color:inherit;font:inherit;outline:none;cursor:pointer}html[data-theme="dark"] #elasticsearch-monitoring-theme-picker{background:#182437;color:#e5eaf3;border-color:#39485e}
</style>
<script>
(function(){var root=document.documentElement,key='elasticsearch-monitoring-theme',labels=['Gündüz','Gece','Sistem'],allowed=['light','dark','system'];function system(){return matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light'}function read(){try{var v=localStorage.getItem(key);return allowed.indexOf(v)>=0?v:'system'}catch(e){return 'system'}}var preference=read();function apply(){var v=preference==='system'?system():preference;root.dataset.theme=v;root.setAttribute('data-bs-theme',v);root.style.colorScheme=v}function mount(){apply();if(document.getElementById('elasticsearch-monitoring-theme-picker'))return;var w=document.createElement('label');w.id='elasticsearch-monitoring-theme-picker';w.innerHTML='<span aria-hidden="true">◐</span><select aria-label="Tema"><option value="light">'+labels[0]+'</option><option value="dark">'+labels[1]+'</option><option value="system">'+labels[2]+'</option></select>';var s=w.querySelector('select');s.value=preference;s.addEventListener('change',function(){preference=s.value;try{localStorage.setItem(key,preference)}catch(e){}apply()});document.body.appendChild(w)}if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',mount,{once:true});else mount();var m=matchMedia('(prefers-color-scheme: dark)');if(m.addEventListener)m.addEventListener('change',function(){if(preference==='system')apply()});else m.addListener(function(){if(preference==='system')apply()})})();
</script>